#include <TFT_eSPI.h>

TFT_eSPI tft = TFT_eSPI();

#define BG TFT_BLACK
#define FG TFT_WHITE
#define DIM 0x7BEF

// Offline starttijd: pas deze aan voordat je compileert.
int startHour = 12;
int startMinute = 0;
int startSecond = 0;

unsigned long bootTime;
unsigned long lastClock = 0;
unsigned long lastGlitch = 0;
unsigned long lastMascot = 0;

int mascotX = 160;
int mascotDir = 1;
int scanY = 0;

bool glitchActive = false;
bool bootFinished = false;

const int SCREEN_W = 320;
const int SCREEN_H = 240;

void centerText(const char* txt, int y, int size, uint16_t color) {
  tft.setTextSize(size);
  tft.setTextColor(color, BG);

  int width = strlen(txt) * 6 * size;
  tft.setCursor((SCREEN_W - width) / 2, y);
  tft.print(txt);
}

void drawLogo(int x, int y, bool shifted = false) {
  int dx = shifted ? 3 : 0;

  // Geometrisch cyber-logo
  tft.drawRect(x - 25 + dx, y - 22, 50, 44, FG);
  tft.drawLine(x - 35 + dx, y - 15,
               x - 25 + dx, y - 15, FG);
  tft.drawLine(x + 25 + dx, y + 15,
               x + 35 + dx, y + 15, FG);

  // Abstracte G-vorm
  tft.drawRect(x - 14 + dx, y - 12, 28, 24, FG);
  tft.fillRect(x - 8 + dx, y - 5, 5, 5, FG);
  tft.fillRect(x + 3 + dx, y - 5, 5, 5, FG);

  tft.drawFastHLine(x + dx, y + 5, 9, FG);
  tft.drawFastHLine(x - 7 + dx, y + 8, 14, FG);
}

void drawBoot() {
  tft.fillScreen(BG);

  centerText("GHOST SYSTEMS", 30, 2, FG);
  centerText("INITIALIZING", 85, 2, FG);

  tft.drawRect(35, 125, 250, 12, FG);

  for (int i = 0; i < 246; i += 5) {
    tft.fillRect(37, 127, i, 8, FG);

    // Scanlijn tijdens de opstart
    tft.drawFastHLine(35, 151, 250, DIM);
    tft.drawFastHLine(35, 151, i, FG);

    delay(18);
  }

  centerText("SYSTEM READY", 175, 2, FG);
  delay(400);
}

void drawInterface() {
  tft.fillScreen(BG);

  tft.setTextSize(1);
  tft.setTextColor(DIM, BG);

  tft.setCursor(8, 8);
  tft.print("GHOST_OS // V1.0");

  tft.setCursor(254, 8);
  tft.print("OFFLINE");

  tft.drawFastHLine(8, 23, 304, DIM);

  drawLogo(160, 65);

  centerText("GHOST//CLOCK", 100, 2, FG);
  centerText("NO SIGNAL. JUST TIME.", 126, 1, DIM);

  tft.drawFastHLine(8, 150, 304, DIM);

  tft.setCursor(8, 222);
  tft.setTextColor(DIM, BG);
  tft.print("CORE: STABLE");

  tft.setCursor(220, 222);
  tft.print("GLITCH: ACTIVE");
}

void drawClock() {
  unsigned long elapsed = (millis() - bootTime) / 1000UL;

  unsigned long total =
      (unsigned long)startHour * 3600UL +
      (unsigned long)startMinute * 60UL +
      (unsigned long)startSecond +
      elapsed;

  total %= 86400UL;

  int h = total / 3600;
  int m = (total / 60) % 60;
  int s = total % 60;

  char timeText[12];
  snprintf(timeText, sizeof(timeText),
           "%02d:%02d:%02d", h, m, s);

  tft.fillRect(45, 170, 230, 38, BG);

  tft.setTextSize(3);
  tft.setTextColor(FG, BG);

  int textWidth = strlen(timeText) * 18;
  tft.setCursor((SCREEN_W - textWidth) / 2, 176);
  tft.print(timeText);
}

void animateLogo() {
  // Wisser alleen het gebied rond het logo.
  tft.fillRect(115, 32, 90, 65, BG);

  mascotX += mascotDir * 2;

  if (mascotX > 166 || mascotX < 154) {
    mascotDir = -mascotDir;
  }

  drawLogo(mascotX, 65, false);

  // Kleine digitale storingsstreep
  if (random(0, 4) == 0) {
    int y = random(43, 87);
    tft.drawFastHLine(random(130, 155), y,
                      random(8, 40), FG);
  }
}

void glitchEffect() {
  // Korte witte glitchlijnen
  for (int i = 0; i < 3; i++) {
    int y = random(30, 155);
    int x = random(0, 260);
    int w = random(15, 75);

    tft.drawFastHLine(x, y, w, FG);
  }

  // Korte verschuiving van het logo
  drawLogo(160, 65, true);
  delay(35);

  // Herstel de normale interface
  drawInterface();
  drawClock();
}

void setup() {
  randomSeed(micros());

  tft.init();
  tft.setRotation(1);
  tft.fillScreen(BG);

  drawBoot();

  bootTime = millis();
  bootFinished = true;

  drawInterface();
  drawClock();
}

void loop() {
  if (!bootFinished) return;

  unsigned long now = millis();

  // Klok verversen
  if (now - lastClock >= 200) {
    lastClock = now;
    drawClock();
  }

  // Bewegend geometrisch logo
  if (now - lastMascot >= 180) {
    lastMascot = now;
    animateLogo();
  }

  // Willekeurige glitch om de paar seconden
  if (now - lastGlitch >= 2500) {
    lastGlitch = now;

    if (random(0, 3) != 0) {
      glitchEffect();
    }
  }
}
